import fs from "node:fs";
import path from "node:path";

const DIR = path.dirname(new URL(import.meta.url).pathname);
const LOG = path.join(DIR, "feature5.log");
const log = (...a) =>
  fs.appendFileSync(LOG, `[${new Date().toISOString()}] ${a.map((x) => (typeof x === "string" ? x : JSON.stringify(x))).join(" ")}\n`);
const shot = (p, name) => p.screenshot({ path: path.join(DIR, name) });

const U = {
  pageA: "e67v5pgAx", introA: "e67v5aInx", A: "e67v5Aclx", A1: "e67v5A1xx", A2: "e67v5A2xx", GC: "e67v5GCxx", tailA: "e67v5aTlx",
  pageB: "e67v5pgBx", B: "e67v5Bopx", B1: "e67v5B1xx",
  pageC: "e67v5pgCx", CP: "e67v5CPxx", C: "e67v5Cxxx", C1: "e67v5C1xx",
  pageN: "e67v5pgNx", N1: "e67v5N1xx", N2: "e67v5N2xx", N3: "e67v5N3xx",
};
const NODE_TITLE = "[[CLM]] - ENG2367v5 regular claim node";
const errors = [];

const closeDialogs = async (page) => {
  for (let i = 0; i < 5; i++) {
    if (!(await page.locator(".bp3-overlay-open").count())) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(300);
  }
};

const readOpen = (page) =>
  page.evaluate((U) => {
    const g = (uid) => {
      const r = window.roamAlphaAPI.pull("[:block/open]", [":block/uid", uid]);
      return r ? (r[":block/open"] === undefined ? "unset" : r[":block/open"]) : "missing";
    };
    return { A: g(U.A), A2: g(U.A2), CP: g(U.CP), B: g(U.B) };
  }, U);

const createData = (page) =>
  page.evaluate(async ({ U, NODE_TITLE }) => {
    const api = window.roamAlphaAPI.data;
    const mk = (parent, order, uid, string, open) =>
      api.block.create({ location: { "parent-uid": parent, order }, block: { uid, string, ...(open === false ? { open: false } : {}) } });
    await api.page.create({ page: { title: "ENG2367v5 Page A", uid: U.pageA } });
    await mk(U.pageA, 0, U.introA, "ENG2367v5 A intro block");
    await mk(U.pageA, 1, U.A, "ENG2367v5 A-collapsed #res-candidate", false);
    await mk(U.A, 0, U.A1, "A-child-one");
    await mk(U.A, 1, U.A2, "A-child-two (collapsed)", false);
    await mk(U.A2, 0, U.GC, "grandchild");
    await mk(U.pageA, 2, U.tailA, "ENG2367v5 A tail block");
    await api.page.create({ page: { title: "ENG2367v5 Page B", uid: U.pageB } });
    await mk(U.pageB, 0, U.B, "ENG2367v5 B-open #res-candidate");
    await mk(U.B, 0, U.B1, "B-child-one");
    await api.page.create({ page: { title: "ENG2367v5 Page C", uid: U.pageC } });
    await mk(U.pageC, 0, U.CP, "C-parent (collapsed)", false);
    await mk(U.CP, 0, U.C, "ENG2367v5 C-under-collapsed-parent #res-candidate");
    await mk(U.C, 0, U.C1, "C-child-one");
    await api.page.create({ page: { title: NODE_TITLE, uid: U.pageN } });
    await mk(U.pageN, 0, U.N1, "Regular node block one");
    await mk(U.pageN, 1, U.N2, "Regular node block two");
    await mk(U.pageN, 2, U.N3, "Regular node block three");
  }, { U, NODE_TITLE });

const openDialog = async (page) => {
  await closeDialogs(page);
  await page.keyboard.press("Meta+p");
  await page.waitForTimeout(400);
  await page.keyboard.type("DG: Open Node Search");
  await page.waitForTimeout(600);
  await page.keyboard.press("Enter");
  const dialog = page.locator(".bp3-dialog").filter({ has: page.locator('[title="Close search"]') }).last();
  await dialog.waitFor({ timeout: 20000 });
  await dialog.getByRole("button", { name: "Display options" }).click();
  const sw = page.locator(".bp3-popover").getByText("Show candidate nodes");
  await sw.waitFor({ timeout: 5000 });
  await sw.click();
  await page.waitForTimeout(300);
  await page.keyboard.press("Escape");
  const input = dialog.locator("input").first();
  await input.click();
  await input.fill("ENG2367v5");
  await dialog.locator('[role="listbox"] [role="option"]').first().waitFor({ timeout: 20000 });
  await page.waitForTimeout(800);
  return dialog;
};

const previewFacts = (dialog, U) =>
  dialog.evaluate((d, U) => {
    const prev = d.querySelector(".overflow-y-auto.border-t .pointer-events-none");
    if (!prev) return { previewFound: false };
    const ids = new Set();
    prev.querySelectorAll("[data-block-uid]").forEach((e) => ids.add(e.getAttribute("data-block-uid")));
    prev.querySelectorAll("[id^='block-input-']").forEach((e) => ids.add(e.id.slice(-9)));
    const label = Object.fromEntries(Object.entries(U).map(([k, v]) => [v, k]));
    const zp = prev.querySelector(".rm-zoom-path");
    return {
      previewFound: true,
      zoomPath: !!zp,
      zoomPathText: zp ? zp.innerText.replace(/\s+/g, " ").trim() : null,
      renderedUids: [...ids].map((u) => label[u] || u),
      pageTitle: prev.querySelector(".rm-title-display, h1")?.innerText ?? null,
      text: prev.innerText.replace(/\s+/g, " ").trim().slice(0, 300),
    };
  }, U);

const selectRow = async (page, dialog, text) => {
  const row = dialog.locator('[role="option"]').filter({ hasText: text }).first();
  await row.click();
  await page.waitForTimeout(1200);
};

export default {
  async ready({ page }) {
    await closeDialogs(page);
    return true;
  },
  async run({ page }) {
    fs.writeFileSync(LOG, "");
    page.on("console", (m) => { if (m.type() === "error") { errors.push(`console: ${m.text()}`); log("CONSOLE ERROR", m.text()); } });
    page.on("pageerror", (e) => { errors.push(`pageerror: ${e.message}`); log("PAGEERROR", e.message); });
    await page.evaluate(() => {
      window.__e2367v5 = [];
      window.addEventListener("unhandledrejection", (e) => window.__e2367v5.push(String(e.reason?.stack || e.reason)));
    });
    const proof = { scenarios: {} };
    await closeDialogs(page);
    await createData(page);
    await page.waitForTimeout(1500);
    proof.openBefore = await readOpen(page);
    log("openBefore", proof.openBefore);

    const dialog = await openDialog(page);
    proof.resultRows = await dialog.locator('[role="option"]').allInnerTexts();
    log("rows", proof.resultRows);
    await shot(page, "r5-0-results.png");

    const errCount = () => errors.length;
    // 1. A-collapsed
    let e0 = errCount();
    await selectRow(page, dialog, "A-collapsed");
    const s1 = await previewFacts(dialog, U);
    s1.openAfter = await readOpen(page);
    s1.childrenVisible = s1.renderedUids?.includes("A1") && s1.renderedUids?.includes("A2");
    s1.grandchildVisible = !!s1.renderedUids?.includes("GC") || /grandchild/.test(s1.text || "");
    s1.newErrors = errors.slice(e0);
    await shot(page, "r5-1-A-collapsed.png");
    proof.scenarios.A = s1;
    log("S1", s1);

    // 2. B-open
    e0 = errCount();
    await selectRow(page, dialog, "B-open");
    const s2 = await previewFacts(dialog, U);
    s2.childVisible = s2.renderedUids?.includes("B1");
    s2.newErrors = errors.slice(e0);
    await shot(page, "r5-2-B-open.png");
    proof.scenarios.B = s2;
    log("S2", s2);

    // 3. C under collapsed parent
    e0 = errCount();
    await selectRow(page, dialog, "C-under-collapsed-parent");
    const s3 = await previewFacts(dialog, U);
    s3.childVisible = s3.renderedUids?.includes("C1");
    s3.openAfter = await readOpen(page);
    s3.newErrors = errors.slice(e0);
    await shot(page, "r5-3-C-under-collapsed.png");
    proof.scenarios.C = s3;
    log("S3", s3);

    // 4. Regular node
    e0 = errCount();
    await selectRow(page, dialog, "regular claim node");
    const s4 = await previewFacts(dialog, U);
    s4.newErrors = errors.slice(e0);
    await shot(page, "r5-4-regular-node.png");
    proof.scenarios.regular = s4;
    log("S4", s4);

    // 5. Rapid arrow switching
    e0 = errCount();
    await dialog.locator("input").first().focus();
    const rowCount = proof.resultRows.length;
    for (let r = 0; r < 3; r++) {
      for (let i = 0; i < rowCount; i++) { await page.keyboard.press("ArrowDown"); await page.waitForTimeout(40); }
      for (let i = 0; i < rowCount; i++) { await page.keyboard.press("ArrowUp"); await page.waitForTimeout(40); }
    }
    await page.waitForTimeout(1500);
    const s5 = await previewFacts(dialog, U);
    s5.activeRow = await dialog.locator('[role="option"][aria-selected="true"]').innerText().catch(() => null);
    s5.openAfter = await readOpen(page);
    s5.newErrors = errors.slice(e0);
    s5.unhandled = await page.evaluate(() => window.__e2367v5);
    await shot(page, "r5-5-after-arrows.png");
    proof.scenarios.arrows = s5;
    log("S5", s5);

    // Main window render of page A
    await closeDialogs(page);
    await page.evaluate((uid) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } }), U.pageA);
    await page.waitForTimeout(2000);
    proof.mainWindowA = await page.evaluate((U) => {
      const art = document.querySelector(".roam-article");
      const has = (uid) => !!art?.querySelector(`[id$='${uid}']`);
      const aMain = art?.querySelector(`[id$='${U.A}']`)?.closest(".roam-block-container");
      return {
        A: has(U.A), A1: has(U.A1), A2: has(U.A2), GC: has(U.GC),
        aCaretClosed: !!aMain?.querySelector(":scope > .rm-block-main .rm-caret-closed"),
        aContainerClass: aMain?.className ?? null,
      };
    }, U);
    proof.openFinal = await readOpen(page);
    await shot(page, "r5-6-main-window-page-A.png");
    log("mainWindowA", proof.mainWindowA, "openFinal", proof.openFinal);
    proof.allErrors = errors;
    proof.unhandled = await page.evaluate(() => window.__e2367v5);
    return proof;
  },
  async cleanup({ page }) {
    await closeDialogs(page);
    const remaining = await page.evaluate(async ({ U, NODE_TITLE }) => {
      await window.roamAlphaAPI.ui.mainWindow.openDailyNotes();
      for (const uid of [U.pageA, U.pageB, U.pageC, U.pageN]) {
        try { await window.roamAlphaAPI.data.page.delete({ page: { uid } }); } catch (e) {}
      }
      await new Promise((r) => setTimeout(r, 1500));
      const pages = window.roamAlphaAPI.q(`[:find ?t :where [?p :node/title ?t] [(clojure.string/includes? ?t "ENG2367v5")]]`).map((r) => r[0]);
      const blocks = window.roamAlphaAPI.q(`[:find ?u :where [?b :block/uid ?u] [(clojure.string/starts-with? ?u "e67v5")]]`).map((r) => r[0]);
      return { pages, blocks, nodeTitleGone: !window.roamAlphaAPI.q(`[:find ?p :in $ ?t :where [?p :node/title ?t]]`, NODE_TITLE).length };
    }, { U, NODE_TITLE });
    log("cleanup remaining", remaining);
    return remaining;
  },
};

